188	    protected Set<Pet> getPetsInternal() {
189	        if (this.pets == null) {
190	            this.pets = new HashSet<>();
191	        }
192	        return this.pets;
193	    }
194	
195	    protected void setPetsInternal(Set<Pet> pets) {
196	        this.pets = pets;
197	    }
198	
199	    public List<Pet> getPets() {
200	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
201	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
202	        return Collections.unmodifiableList(sortedPets);
203	    }
204	
205	    public void setPets(List<Pet> pets) {
206	        this.pets = new HashSet<>(pets);
207	    }
208	
209	    public void addPet(Pet pet) {
210	        getPetsInternal().add(pet);
211	        pet.setOwner(this);
212	    }
213	
214	    /**
215	     * Return the Pet with the given name, or null if none found for this Owner.
216	     *
217	     * @param name to test
218	     * @return true if pet name is already in use
219	     */
220	    public Pet getPet(String name) {
221	        return getPet(name, false);
222	    }
223	
224	    /**
225	     * Return the Pet with the given name, or null if none found for this Owner.
226	     *
227	     * @param name to test
228	     * @return true if pet name is already in use
229	     */
230	    public Pet getPet(String name, boolean ignoreNew) {
231	        name = name.toLowerCase();
232	        for (Pet pet : getPetsInternal()) {
233	            if (!ignoreNew || !pet.isNew()) {
234	                String compName = pet.getName();
235	                compName = compName.toLowerCase();
236	                if (compName.equals(name)) {
237	                    return pet;
238	                }
239	            }
240	        }
241	        return null;
242	    }
243	
244	    public Pet getPet(Integer petId) {
245	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
246	    }
247	
248	    @Override
249	    public String toString() {
250	        return new ToStringCreator(this)
251	
252	            .append("id", this.getId())
253	            .append("new", this.isNew())
254	            .append("lastName", this.getLastName())
255	            .append("firstName", this.getFirstName())
256	            .append("address", this.address)
257	            .append("city", this.city)
258	            .append("telephone", this.telephone)
259	            .toString();
260	    }
261	}
