1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	import java.util.Map;
8	
9	/**
10	 * Derives an owner's {@code customerCode} — the owner's region-and-hash identity,
11	 * formatted {@code <REGION>-<HASH8>}:
12	 *
13	 * <ul>
14	 * <li>{@code REGION} is the region code derived from the postcode: look the postcode up
15	 * against the inclusive region ranges (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and,
16	 * only when the postcode is absent or in no known range, fall back to the fixed
17	 * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), else
18	 * {@code UNKNOWN}.</li>
19	 * <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
20	 * {@code normalizedTelephone + lastName}, where the telephone is normalized to E.164 form
21	 * (an absent or unparseable telephone contributes an empty string).</li>
22	 * </ul>
23	 *
24	 * <p>The whole owner identity — the {@code customerCode} itself, the values built from it
25	 * (membership number and its Luhn check digit), the create audit record and the derived
26	 * locality — flows from this single value. There is no sequence number.
27	 *
28	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
29	 * tripping the one-public-method-per-function rule.
30	 */
31	public final class OwnerCustomerCode {
32	
33	    /** City -> canonical region, matching the fixed table used to validate postcodes. */
34	    private static final Map<String, String> CITY_REGION = Map.of(
35	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
36	
37	    /** Region -> inclusive 4-digit postcode range {low, high}. */
38	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
39	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
40	
41	    private OwnerCustomerCode() {
42	    }
43	
44	    /** The full {@code <REGION>-<HASH8>} customer code for the given owner fields. */
45	    public static String of(String postcode, String city, String telephone, String lastName) {
46	        return region(postcode, city) + "-" + hash8(telephone, lastName);
47	    }
48	
49	    /**
50	     * The region code derived from the postcode (range lookup), falling back to the fixed
51	     * city-to-region table when the postcode is absent or in no known range, else
52	     * {@code UNKNOWN}.
53	     */
54	    public static String region(String postcode, String city) {
55	        if (postcode != null) {
56	            try {
57	                int value = Integer.parseInt(postcode.trim());
58	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
59	                    int[] range = entry.getValue();
60	                    if (value >= range[0] && value <= range[1]) {
61	                        return entry.getKey();
62	                    }
63	                }
64	            }
65	            catch (NumberFormatException ex) {
66	                // not a numeric postcode; fall back to the city table
67	            }
68	        }
69	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
70	    }
71	
72	    /**
73	     * The first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone +
74	     * lastName}, where the telephone is normalized to E.164 (an absent or unparseable
75	     * telephone, or an absent last name, contributes an empty string).
76	     */
77	    public static String hash8(String telephone, String lastName) {
78	        String tel = E164Telephone.normalizeOrNull(telephone);
79	        String normalizedTelephone = tel == null ? "" : tel;
80	        String last = lastName == null ? "" : lastName;
81	        return sha256Hex(normalizedTelephone + last).substring(0, 8).toUpperCase(Locale.ROOT);
82	    }
83	
84	    private static String sha256Hex(String input) {
85	        try {
86	            byte[] digest = MessageDigest.getInstance("SHA-256")
87	                    .digest(input.getBytes(StandardCharsets.UTF_8));
88	            StringBuilder sb = new StringBuilder(digest.length * 2);
89	            for (byte b : digest) {
90	                sb.append(String.format("%02x", b));
91	            }
92	            return sb.toString();
93	        }
94	        catch (NoSuchAlgorithmException ex) {
95	            throw new IllegalStateException("SHA-256 not available", ex);
96	        }
97	    }
98	}
