1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import net.officefloor.plugin.section.clazz.Parameter;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ResponseEntity;
7	
8	/**
9	 * Responds 400 to an {@link InvalidPostcodeException}: the supplied postcode was not a
10	 * 4-digit code or was out of range for the owner's city region.
11	 */
12	public class InvalidPostcodeHandler {
