178	     * digits contained in the {@code customerCode}. Returns null when the customer code is
179	     * absent (e.g. unmigrated seed data).
180	     */
181	    default Integer toCheckDigit(Owner owner) {
182	        String customerCode = owner.getCustomerCode();
183	        if (customerCode == null) {
184	            return null;
185	        }
186	        int sum = 0;
187	        boolean dbl = true;
188	        for (int i = customerCode.length() - 1; i >= 0; i--) {
189	            char c = customerCode.charAt(i);
190	            if (c < '0' || c > '9') {
191	                continue;
192	            }
193	            int d = c - '0';
194	            if (dbl) {
