1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create-owner request that lands in an existing household. Because the
11	 * {@code householdId} is now derived deterministically from (last name, postcode) (see
12	 * {@link AssignHousehold}), any existing owner sharing the new owner's {@code householdId}
13	 * <em>is</em> the same household, so a second such owner is a household duplicate and is
14	 * rejected 409 via {@link DuplicateIdentityException}.
15	 *
16	 * <p>{@code sharesHousehold} bypasses this block: the caller is declaring the owner a
17	 * genuine additional member of that household, so the create is allowed. (It no longer
18	 * creates any link — the shared identifier is implicit in the last name and postcode.)
19	 *
20	 * <p>Runs after {@link AssignHousehold} (so the new owner's {@code householdId} is set) and
21	 * within the create transaction, but before {@link SaveOwner}, so the new owner is not yet
22	 * persisted and cannot collide with itself.
23	 */
24	public class RejectDuplicateIdentity {
25	
26	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return; // declared household member — bypass the duplicate block
30	        }
31	        String householdId = owner.getHouseholdId();
32	        if (householdId == null) {
33	            return;
34	        }
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
37	                continue;
38	            }
39	            if (householdId.equals(existing.getHouseholdId())) {
40	                throw new DuplicateIdentityException(
41	                        "Another owner with the same identity already exists");
42	            }
43	        }
44	    }
45	}
