1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the owner's {@code customerCode}, the region-and-hash identity formatted
12	 * {@code <REGION>-<HASH8>} where REGION is the region code derived from the postcode and
13	 * HASH8 is the first 8 upper-case hex characters of SHA-256 over
14	 * {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no sequence
15	 * number; see {@link OwnerCustomerCode} for the exact derivation.
16	 *
17	 * <p>De-duplication: when the computed code already belongs to another owner, {@code -<n>} is
18	 * appended with the smallest {@code n} of 2 or more that makes it unique (so a first
19	 * collision yields {@code <base>-2}, the next {@code <base>-3}, and so on). The owner ends up
20	 * with the de-duplicated {@code customerCode}.
21	 *
22	 * <p>Runs after {@code BuildOwner} (so the owner exists, with its telephone already
23	 * normalized to E.164) but before {@code SaveOwner} (so the owner being created is not yet
24	 * persisted and cannot collide with itself), mutating the owner in place.
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String base = OwnerCustomerCode.of(
30	                owner.getPostcode(), owner.getCity(), owner.getTelephone(), owner.getLastName());
31	
32	        Set<String> existing = new HashSet<>();
33	        for (Owner other : ownerRepository.findAll()) {
34	            if (owner.getId() != null && owner.getId().equals(other.getId())) {
35	                continue; // never de-duplicate against the owner being created
36	            }
37	            String code = other.getCustomerCode();
38	            if (code != null) {
39	                existing.add(code);
40	            }
41	        }
42	
43	        String code = base;
44	        for (int n = 2; existing.contains(code); n++) {
45	            code = base + "-" + n;
46	        }
47	        owner.setCustomerCode(code);
48	    }
49	}
