14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
25	    @Mapping(target = "membershipPoints", expression = "java(toMembershipPoints(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
28	    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
29	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
30	    @Mapping(target = "identityKey", expression = "java(toIdentityKey(owner))")
31	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    /**
36	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted
37	     * for humans (see {@link org.springframework.samples.petclinic.rest.function.owner.E164Telephone#display}).
38	     * The raw {@code telephone} is left in E.164 form.
39	     */
40	    default String toTelephoneDisplay(Owner owner) {
41	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
42	                .display(owner.getTelephone());
43	    }
44	
45	    /**
46	     * Derives the owner's {@code ageBand} from its {@code birthDate} measured against its
47	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64,
48	     * {@code SENIOR} at 65 or older. Returns null when either date is absent (so no band is
49	     * reported for owners with no supplied birth date).
50	     */
51	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
52	        java.time.LocalDate birthDate = owner.getBirthDate();
53	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
54	        if (birthDate == null || registrationDate == null) {
55	            return null;
56	        }
57	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
58	        if (age < 18) {
59	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
60	        }
61	        if (age < 65) {
62	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
63	        }
64	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
65	    }
66	
67	    /**
68	     * Derives the owner's {@code identityKey}: the single value that consolidates all
69	     * duplicate detection, {@code normalizedTelephone + '|' + (email or empty) + '|' +
70	     * (householdId or empty)}.
71	     */
72	    default String toIdentityKey(Owner owner) {
73	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner);
74	    }
75	
76	    /**
77	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
78	     * otherwise {@code PHONE}.
79	     */
80	    default String toContactPreference(Owner owner) {
81	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
82	        return hasEmail ? "EMAIL" : "PHONE";
83	    }
84	
85	    /**
86	     * Derives the owner's locality (region) from its region-and-hash identity: the
87	     * {@code customerCode} is {@code <REGION>-<HASH8>}, so the locality is the REGION segment
88	     * preceding the hash. Falls back to deriving the region directly from the postcode/city
89	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode})
90	     * only for unmigrated owners that carry no customer code.
91	     */
92	    default String toLocality(Owner owner) {
93	        String customerCode = owner.getCustomerCode();
94	        if (customerCode != null) {
95	            int dash = customerCode.indexOf('-');
96	            if (dash > 0) {
97	                return customerCode.substring(0, dash);
98	            }
99	        }
100	        return org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
101	                .region(owner.getPostcode(), owner.getCity());
102	    }
103	
104	    /** Region -> IANA timezone, the pinned region-to-timezone table. */
105	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
106	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
107	
108	    /**
109	     * Derives the owner's {@code timezone}: the IANA name for the owner's locality/region via
110	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
111	     * QLD-&gt;Australia/Brisbane). Returns null when the region yields no known timezone (e.g.
112	     * an {@code UNKNOWN} locality).
113	     */
114	    default String toTimezone(Owner owner) {
115	        return REGION_TIMEZONE.get(toLocality(owner));
116	    }
117	
118	    /**
119	     * Derives the owner's membership points: start at 0; add 2 when an email is present; add 1
120	     * when the owner has no namesakes ({@code namesakeCount} is 0); add 2 for a household of 3 or
121	     * more ({@code householdSize} at least 3); add 3 for tenure over 365 days (a
122	     * {@code registrationDate} more than 365 days ago). A newly created owner has zero tenure.
123	     */
124	    default Integer toMembershipPoints(Owner owner) {
125	        int points = 0;
126	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
127	        if (hasEmail) {
128	            points += 2;
129	        }
130	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
131	        if (unique) {
132	            points += 1;
133	        }
134	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
135	            points += 2;
136	        }
137	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
138	        if (registrationDate != null && java.time.temporal.ChronoUnit.DAYS
139	                .between(registrationDate, java.time.LocalDate.now()) > 365) {
140	            points += 3;
141	        }
142	        return points;
143	    }
