147	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
148	     */
149	    default Integer toMembershipLevel(Owner owner) {
150	        int points = toMembershipPoints(owner);
151	        if (points >= 6) {
152	            return 4;
153	        }
154	        if (points >= 4) {
155	            return 3;
156	        }
157	        if (points >= 2) {
158	            return 2;
159	        }
160	        return 1;
161	    }
