165	     * last two digits of the registration-date year (e.g. {@code NSW-1A2B3C4D-M26}). Returns
166	     * null when either the customer code or registration date is absent (e.g. unmigrated seed
167	     * data).
168	     */
169	    default String toMembershipNumber(Owner owner) {
170	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
171	            return null;
172	        }
173	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
174	    }
